package ama.storage;
import ama.db.TransactionRunner;import javax.sql.DataSource;import java.sql.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
/** Actual TransactionRunner over inert physical JDBC; verifies delegated SQL/commit boundaries only. */
class Task11B3LifecycleFaultTest {
 static final String TASK="selected-task",EX="selected-execution",SCOPE="selected-scope";
 static final String RECEIPT="INSERT INTO idempotency_record(scope_hash,operation) VALUES (?,'PUBLICATION_LOCAL_RECOVERY')",ATTEMPT="UPDATE task_attempt SET ended_at=UTC_TIMESTAMP(6),outcome=?,error_code=? WHERE task_id=? AND attempt=? AND owner=? AND ended_at IS NULL",MARK="UPDATE external_execution SET state='MARKED',task_attempt=?,marked_at=? WHERE id=?",FLUSH="UPDATE task_outbox_sequence SET next_id=next_id+1 WHERE id=1";
 void local(JdbcTemplate jdbc,String scope){jdbc.update(RECEIPT,scope);jdbc.update(ATTEMPT,"FAILED","EXPIRED_UNMARKED_ABANDONED",TASK,1L,"worker");}
 void mark(JdbcTemplate jdbc,String execution){jdbc.update(MARK,1L,java.time.LocalDateTime.of(2026,10,26,6,0),execution);jdbc.update(FLUSH);}
 @Test void selectedRealAttemptEndFailsOnlyAfterExecutionAndReturnedRollback(){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3LifecycleFault();DataSource source=fault.wrap(fake);fault.armAttempt(TASK,SCOPE);assertThrows(RuntimeException.class,()->new TransactionRunner(source).required(()->{local(new JdbcTemplate(source),SCOPE);return null;}));assertTrue(fault.attemptHit);assertTrue(fault.attemptRollbackReturned);assertTrue(fake.sql.contains(ATTEMPT));assertEquals(0,fake.commits);assertEquals(1,fake.rollbacks);}
 @Test void foreignReceiptScopeDoesNotTriggerAttemptFault(){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3LifecycleFault();DataSource source=fault.wrap(fake);fault.armAttempt(TASK,SCOPE);new TransactionRunner(source).required(()->{local(new JdbcTemplate(source),"other-scope");return null;});assertFalse(fault.attemptHit);assertEquals(1,fake.commits);}
 @Test void failedActualRollbackIsNeverCredited(){var fake=new Task11B3LocalFaultTest.Fake();fake.rollbackThrows=true;var fault=new Task11B3LifecycleFault();DataSource source=fault.wrap(fake);fault.armAttempt(TASK,SCOPE);assertThrows(RuntimeException.class,()->new TransactionRunner(source).required(()->{local(new JdbcTemplate(source),SCOPE);return null;}));assertTrue(fault.attemptHit);assertFalse(fault.attemptRollbackReturned);}
 @Test void heldMarkerRollsBackBeforeAnyPhysicalCommitAndReturnsNoResult()throws Exception {var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3LifecycleFault();DataSource source=fault.wrap(fake);fault.armMarker(Task11B3LifecycleFault.Marker.ROLLBACK_BEFORE_COMMIT,TASK,EX);var executor=Executors.newSingleThreadExecutor();try{var returned=new AtomicBoolean();var future=executor.submit(()->{new TransactionRunner(source).required(()->{mark(new JdbcTemplate(source),EX);return null;});returned.set(true);});assertTrue(fault.entered.await(1,TimeUnit.SECONDS));assertFalse(future.isDone());assertEquals(0,fake.commits);fault.release.countDown();assertThrows(ExecutionException.class,()->future.get(2,TimeUnit.SECONDS));assertTrue(fault.markerRollbackReturned);assertFalse(fault.markerCommitReturned);assertFalse(returned.get());assertEquals(0,fake.commits);assertEquals(1,fake.rollbacks);}finally{fault.release.countDown();executor.shutdownNow();assertTrue(executor.awaitTermination(3,TimeUnit.SECONDS));}}
 @Test void markerLostAckOccursAfterPhysicalCommitButCallerGetsNoResult(){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3LifecycleFault();DataSource source=fault.wrap(fake);fault.armMarker(Task11B3LifecycleFault.Marker.COMMIT_THEN_LOSE_ACK,TASK,EX);var returned=new AtomicBoolean();assertThrows(RuntimeException.class,()->{new TransactionRunner(source).required(()->{mark(new JdbcTemplate(source),EX);return null;});returned.set(true);});assertTrue(fault.markerCommitReturned);assertFalse(fault.markerRollbackReturned);assertFalse(returned.get());assertEquals(1,fake.commits);assertEquals(0,fake.rollbacks);}
 @Test void foreignExecutionCannotConsumeMarkerFault(){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3LifecycleFault();DataSource source=fault.wrap(fake);fault.armMarker(Task11B3LifecycleFault.Marker.COMMIT_THEN_LOSE_ACK,TASK,EX);var failure=assertThrows(AssertionError.class,()->new TransactionRunner(source).required(()->{mark(new JdbcTemplate(source),"other-execution");return null;}));assertEquals("Unreleased publication marker write",failure.getMessage());assertFalse(fake.sql.contains(MARK));assertFalse(fault.markerCommitReturned);assertEquals(0,fake.commits);}
 @Test void unreleasedWorkerMarkerCannotReachPhysicalStatement(){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3LifecycleFault();DataSource source=fault.wrap(fake);var failure=assertThrows(AssertionError.class,()->new TransactionRunner(source).required(()->{mark(new JdbcTemplate(source),EX);return null;}));assertEquals("Unreleased publication marker write",failure.getMessage());assertFalse(fake.sql.contains(MARK));assertEquals(0,fake.commits);assertEquals(1,fake.rollbacks);}
 @Test void lifecycleCannotCreateAnUnreleasedNewOperationRoot(){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3LifecycleFault();DataSource source=fault.wrap(fake);String insert="INSERT INTO external_operation(id,state) VALUES (?,'MARKED')";var failure=assertThrows(AssertionError.class,()->new TransactionRunner(source).required(()->{new JdbcTemplate(source).update(insert,"unreleased-root");return null;}));assertEquals("New operation roots forbidden in B3 lifecycle",failure.getMessage());assertFalse(fake.sql.contains(insert));assertEquals(0,fake.commits);}
 @Test void disarmedWrapperKeepsTheActualBoundConnectionIdentity(){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3LifecycleFault();DataSource source=fault.wrap(fake);new TransactionRunner(source).required(()->{Connection connection=DataSourceUtils.getConnection(source);assertSame(connection,connection.unwrap(Connection.class));try(var statement=connection.prepareStatement("SELECT 1")){assertSame(connection,statement.getConnection());}DataSourceUtils.releaseConnection(connection,source);return null;});assertEquals(1,fake.commits);}
 @Test void lockObservationSpansTheActualDelegatedCallAndClearsOnSuccessAndFailure()throws Exception {
  for(boolean failPhysical:new boolean[]{false,true}){
   var fake=new Task11B3LocalFaultTest.Fake();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);String sql="SELECT id FROM meeting WHERE id=? FOR UPDATE";
   DataSource delegated=new AbstractDataSource(){public Connection getConnection(){var physical=fake.getConnection();return (Connection)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(p,m,args)->{if(m.getName().equals("prepareStatement")&&sql.equals(args[0])){var statement=(PreparedStatement)m.invoke(physical,args);return Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{PreparedStatement.class},(sp,sm,sa)->{if(sm.getName().equals("execute")){entered.countDown();assertTrue(release.await(2,TimeUnit.SECONDS));if(failPhysical)throw new SQLException("Owned physical SELECT unavailable");return false;}return Task11B3LifecycleFault.invoke(statement,sm,sa);});}return Task11B3LifecycleFault.invoke(physical,m,args);});}public Connection getConnection(String u,String p){throw new AssertionError("No credentials");}};
   var fault=new Task11B3LifecycleFault();DataSource source=fault.wrap(delegated);fault.armAttempt(TASK,SCOPE);var executor=Executors.newSingleThreadExecutor();
   try{var future=executor.submit(()->new TransactionRunner(source).required(()->{new JdbcTemplate(source).update(RECEIPT,SCOPE);Connection connection=DataSourceUtils.getConnection(source);try(var statement=connection.prepareStatement(sql)){statement.setString(1,"selected-meeting");return statement.execute();}finally{DataSourceUtils.releaseConnection(connection,source);}}));assertTrue(entered.await(1,TimeUnit.SECONDS));var flight=fault.recoveryFlight.get();assertNotNull(flight);assertEquals(sql,flight.sql());assertFalse(future.isDone());assertTrue(System.nanoTime()>=flight.openedNanos());release.countDown();if(failPhysical)assertThrows(ExecutionException.class,()->future.get(2,TimeUnit.SECONDS));else assertFalse(future.get(2,TimeUnit.SECONDS));assertNull(fault.recoveryFlight.get());assertFalse(fault.attemptHit);assertEquals(failPhysical?0:1,fake.commits);assertEquals(failPhysical?1:0,fake.rollbacks);}
   finally{release.countDown();Task11B3LifecycleFixture.join(executor);}
  }
 }
}